#!/usr/bin/env python3
"""Independent host/Unicorn gate for auth_integrated_bench.asm.

86Box on an original-speed 4.77 MHz profile remains the timing authority.
This checker establishes the exact semantic and memory boundary before that
slow run:

* the deterministic vector include is byte-for-byte regenerated by the strict
  host oracle;
* host X.509/SPKI/profile/scheme/context/time and Brotli gates pass;
* the exact ``cpu 8086`` image fits the literal 16 KiB ROM-BASIC load window;
* target DER/r/s and affine-point rejection gates are exercised directly;
* both target ECDSA equations return the independent host r/u1/u2 values; and
* executable/data/stack and resumable-loop state are reported separately.
"""

from __future__ import annotations

import hashlib
import importlib.util
import json
import re
import struct
import subprocess
import sys
import tempfile
from pathlib import Path

from unicorn import UC_ARCH_X86, UC_HOOK_CODE, UC_MODE_16, Uc
from unicorn.x86_const import (
    UC_X86_REG_AX,
    UC_X86_REG_BX,
    UC_X86_REG_CX,
    UC_X86_REG_DI,
    UC_X86_REG_DS,
    UC_X86_REG_EFLAGS,
    UC_X86_REG_ES,
    UC_X86_REG_SI,
    UC_X86_REG_SP,
    UC_X86_REG_SS,
)


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
SOURCE = HERE / "auth_integrated_bench.asm"
VECTORS = HERE / "auth_integrated_vectors.inc"
ORACLE_SOURCE = HERE / "auth_integrated_oracle.py"
P256_SOURCE = ROOT / "targets/ibm_pc_5150/boot/core/p256.inc"
ORIGIN = 0x1000
PHYSICAL_RAM_CEILING = 0x4000
ROM_BASIC_LOADER = 0x3A00
STACK_TOP = 0x3FF0
RETURN_SENTINEL = 0x0FFE


def load_oracle():
    spec = importlib.util.spec_from_file_location(
        "seed_auth_integrated_oracle", ORACLE_SOURCE
    )
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot load authentication oracle")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


ORACLE = load_oracle()


def assemble(directory: Path) -> tuple[bytes, list[str]]:
    binary = directory / "auth_integrated.bin"
    listing = directory / "auth_integrated.lst"
    subprocess.run(
        [
            "nasm",
            "-f",
            "bin",
            f"-I{ROOT / 'targets/ibm_pc_5150/boot'}/",
            f"-I{ROOT / 'tools/crypto-bench'}/",
            "-l",
            str(listing),
            "-o",
            str(binary),
            str(SOURCE),
        ],
        check=True,
    )
    return binary.read_bytes(), listing.read_text().splitlines()


def label_address(listing: list[str], label: str) -> int:
    label_pattern = re.compile(
        rf"\b{re.escape(label)}(?::|\s+(?:db|dw|dd|dq|times)\b)"
    )
    offset_pattern = re.compile(r"\s([0-9A-F]{8})\s")
    for index, line in enumerate(listing):
        if not label_pattern.search(line):
            continue
        for candidate in listing[index:]:
            match = offset_pattern.search(candidate)
            if match:
                return ORIGIN + int(match.group(1), 16)
    raise RuntimeError(f"missing NASM listing label: {label}")


def rounded_load_end(image: bytes) -> int:
    return ORIGIN + ((len(image) + 511) // 512) * 512


def new_machine(image: bytes) -> Uc:
    machine = Uc(UC_ARCH_X86, UC_MODE_16)
    machine.mem_map(0, 0x10000)
    machine.mem_write(ORIGIN, image)
    machine.reg_write(UC_X86_REG_DS, 0)
    machine.reg_write(UC_X86_REG_ES, 0)
    machine.reg_write(UC_X86_REG_SS, 0)
    machine.reg_write(UC_X86_REG_EFLAGS, 2)
    machine.mem_write(
        rounded_load_end(image),
        bytes([0xA5]) * (STACK_TOP - rounded_load_end(image)),
    )
    return machine


def invoke(
    machine: Uc,
    entry: int,
    *,
    registers: dict[int, int] | None = None,
    instruction_limit: int = 500_000_000,
) -> tuple[int, bool]:
    if registers:
        for register, value in registers.items():
            machine.reg_write(register, value)
    machine.reg_write(UC_X86_REG_SP, STACK_TOP - 2)
    machine.mem_write(STACK_TOP - 2, struct.pack("<H", RETURN_SENTINEL))

    def stop_at_return(
        emulator: Uc, _address: int, _size: int, _data: object
    ) -> None:
        emulator.emu_stop()

    hook = machine.hook_add(
        UC_HOOK_CODE,
        stop_at_return,
        begin=RETURN_SENTINEL,
        end=RETURN_SENTINEL,
    )
    try:
        machine.emu_start(entry, 0, count=instruction_limit)
    finally:
        machine.hook_del(hook)
    if machine.reg_read(UC_X86_REG_SP) != STACK_TOP:
        raise AssertionError("target routine did not return before instruction cap")
    return (
        machine.reg_read(UC_X86_REG_AX),
        bool(machine.reg_read(UC_X86_REG_EFLAGS) & 1),
    )


def words_value(machine: Uc, address: int) -> int:
    return int.from_bytes(machine.mem_read(address, 32), "little")


def stack_high_water(machine: Uc, image: bytes) -> int:
    start = rounded_load_end(image)
    guard = bytes(machine.mem_read(start, STACK_TOP - start))
    touched = [index for index, value in enumerate(guard) if value != 0xA5]
    return len(guard) - min(touched) if touched else 0


def target_der_matrix(
    image: bytes, addresses: dict[str, int], fixture
) -> dict[str, object]:
    good_cases = {
        "certificate": fixture.certificate_signature,
        "certificate_verify": fixture.certificate_verify_signature,
    }
    good_results: dict[str, object] = {}
    for name, signature in good_cases.items():
        machine = new_machine(image)
        machine.mem_write(0x0800, signature)
        _, carry = invoke(
            machine,
            addresses["auth_parse_signature"],
            registers={
                UC_X86_REG_SI: 0x0800,
                UC_X86_REG_CX: len(signature),
            },
        )
        if carry:
            raise AssertionError(f"target rejected canonical {name} signature")
        r, s = ORACLE.parse_signature(signature)
        if words_value(machine, addresses["auth_r"]) != r:
            raise AssertionError(f"target {name} r mismatch")
        if words_value(machine, addresses["auth_s"]) != s:
            raise AssertionError(f"target {name} s mismatch")
        good_results[name] = {
            "der_bytes": len(signature),
            "r": hex(r),
            "s": hex(s),
        }

    rejected = {
        "long-form-sequence-length": (
            b"\x30\x81\x06\x02\x01\x01\x02\x01\x01"
        ),
        "r-zero": ORACLE._sequence(
            ORACLE._integer(0), ORACLE._integer(1)
        ),
        "s-at-n": ORACLE._sequence(
            ORACLE._integer(1), ORACLE._integer(ORACLE.N)
        ),
        "redundant-r-padding": bytes.fromhex("300702020001020101"),
        "negative-r": bytes.fromhex("3006020180020101"),
        "trailing-object": bytes.fromhex("300602010102010100"),
    }
    for name, signature in rejected.items():
        machine = new_machine(image)
        machine.mem_write(0x0800, signature)
        _, carry = invoke(
            machine,
            addresses["auth_parse_signature"],
            registers={
                UC_X86_REG_SI: 0x0800,
                UC_X86_REG_CX: len(signature),
            },
        )
        if not carry:
            raise AssertionError(f"target DER parser accepted {name}")
    return {
        "accepted": good_results,
        "rejected": sorted(rejected),
    }


def target_point_matrix(
    image: bytes, addresses: dict[str, int], fixture
) -> dict[str, object]:
    cases = {
        "anchor": fixture.anchor_point,
        "leaf": fixture.leaf_point,
    }
    for name, (x, y) in cases.items():
        machine = new_machine(image)
        machine.mem_write(0x0800, x.to_bytes(32, "little"))
        machine.mem_write(0x0820, y.to_bytes(32, "little"))
        _, carry = invoke(
            machine,
            addresses["auth_validate_point"],
            registers={
                UC_X86_REG_SI: 0x0800,
                UC_X86_REG_DI: 0x0820,
            },
        )
        if carry:
            raise AssertionError(f"target rejected valid {name} point")

    rejected = {
        "off-curve": (1, 1),
        "x-at-p": (ORACLE.P, fixture.leaf_point[1]),
        "y-at-p": (fixture.leaf_point[0], ORACLE.P),
    }
    for name, (x, y) in rejected.items():
        machine = new_machine(image)
        machine.mem_write(0x0800, x.to_bytes(32, "little"))
        machine.mem_write(0x0820, y.to_bytes(32, "little"))
        _, carry = invoke(
            machine,
            addresses["auth_validate_point"],
            registers={
                UC_X86_REG_SI: 0x0800,
                UC_X86_REG_DI: 0x0820,
            },
        )
        if not carry:
            raise AssertionError(f"target point gate accepted {name}")
    return {
        "accepted": sorted(cases),
        "rejected": sorted(rejected),
        "sec1_spki_encoding_parser": False,
    }


def target_equations(
    image: bytes, addresses: dict[str, int], fixture
) -> dict[str, object]:
    machine = new_machine(image)
    ax, carry = invoke(machine, addresses["auth_prepare"])
    if carry:
        raise AssertionError("target point/table preparation failed")

    results: dict[str, object] = {}
    stages = (
        (
            "leaf_under_we1",
            "auth_verify_certificate",
            fixture.certificate_digest,
            fixture.certificate_signature,
        ),
        (
            "tls_certificate_verify",
            "auth_verify_certificate_verify",
            fixture.certificate_verify_digest,
            fixture.certificate_verify_signature,
        ),
    )
    for index, (name, entry, digest, signature) in enumerate(stages):
        if index:
            _, carry = invoke(machine, addresses["auth_build_leaf_table"])
            if carry:
                raise AssertionError("target leaf table generation failed")
        expected = ORACLE.ecdsa_intermediates(digest, signature)
        _, carry = invoke(machine, addresses[entry])
        if carry:
            raise AssertionError(f"target ECDSA equation failed: {name}")
        actual = {
            key: words_value(machine, addresses[f"auth_{key}"])
            for key in ("r", "s", "z", "w", "u1", "u2")
        }
        for key, expected_value in expected.items():
            if actual[key] != expected_value:
                raise AssertionError(f"target {name} {key} mismatch")
        result_x = words_value(machine, addresses["auth_result_x"])
        if result_x != expected["r"]:
            raise AssertionError(f"target {name} x mod n mismatch")
        results[name] = {
            "passes": True,
            "r": hex(expected["r"]),
            "u1": hex(expected["u1"]),
            "u2": hex(expected["u2"]),
            "x_mod_n": hex(result_x),
        }

    full_machine = new_machine(image)
    ax, carry = invoke(
        full_machine,
        addresses["auth_integrated_gate"],
    )
    if carry or ax != 1:
        raise AssertionError("combined target authentication gate failed")
    return {
        "combined_gate": True,
        "equations": results,
        "unicorn_stack_bytes_no_bios_irq": stack_high_water(
            full_machine, image
        ),
    }


def git_revision() -> str:
    result = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=ROOT,
        capture_output=True,
        text=True,
        check=True,
    )
    return result.stdout.strip()


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    fixture = ORACLE.make_fixture()
    host = ORACLE.report(fixture)
    generated_vectors = ORACLE.vectors_include(fixture)
    if VECTORS.read_text() != generated_vectors:
        raise AssertionError(
            "auth_integrated_vectors.inc differs from strict oracle output"
        )

    with tempfile.TemporaryDirectory(prefix="seed-auth-integrated-") as temp:
        image, listing = assemble(Path(temp))

    labels = (
        "auth_integrated_gate",
        "auth_prepare",
        "auth_verify_certificate",
        "auth_build_leaf_table",
        "auth_verify_certificate_verify",
        "auth_parse_signature",
        "auth_validate_point",
        "auth_p256_code_start",
        "p256_w_tableX",
        "p256_prime",
        "auth_order_n",
        "auth_g_table_x",
        "auth_r",
        "auth_s",
        "auth_z",
        "auth_w",
        "auth_u1",
        "auth_u2",
        "auth_result_x",
        "auth_result_y",
        "tag_authprep",
    )
    addresses = {
        label: label_address(listing, label)
        for label in labels
    }

    content_end = ORIGIN + len(image)
    load_end = rounded_load_end(image)
    if load_end > ROM_BASIC_LOADER:
        raise AssertionError("sector-rounded image overlaps ROM BASIC loader")
    if content_end > PHYSICAL_RAM_CEILING:
        raise AssertionError("image crosses physical 16 KiB ceiling")

    executable_end = addresses["p256_w_tableX"]
    vector_start = addresses["auth_order_n"]
    work_start = addresses["auth_g_table_x"]
    strings_start = addresses["tag_authprep"]
    resumable_breakdown = {
        "jacobian_xyz": 96,
        "g_and_q_width4_tables": 512,
        "u1_and_u2": 64,
        "r": 32,
        "loop_index": 2,
    }
    if sum(resumable_breakdown.values()) != 706:
        raise AssertionError("resumable state ledger drift")

    result = {
        "provenance": {
            "git_head": git_revision(),
            "source": str(SOURCE.relative_to(ROOT)),
            "source_sha256": sha256_file(SOURCE),
            "vectors": str(VECTORS.relative_to(ROOT)),
            "vectors_sha256": sha256_file(VECTORS),
            "p256_source": str(P256_SOURCE.relative_to(ROOT)),
            "p256_source_sha256": sha256_file(P256_SOURCE),
            "assembled_image_sha256": hashlib.sha256(image).hexdigest(),
            "nasm_cpu": "8086",
        },
        "memory": {
            "physical_ram_bytes": PHYSICAL_RAM_CEILING,
            "content_bytes": len(image),
            "content_range": [
                f"0x{ORIGIN:04x}",
                f"0x{content_end:04x}",
            ],
            "sector_rounded_load_end": f"0x{load_end:04x}",
            "rom_basic_loader_start": f"0x{ROM_BASIC_LOADER:04x}",
            "within_literal_16k_and_loader_window": True,
            "executable_and_header_bytes": executable_end - ORIGIN,
            "auth_harness_executable_bytes": (
                addresses["auth_p256_code_start"] - ORIGIN
            ),
            "included_p256_executable_bytes": (
                executable_end - addresses["auth_p256_code_start"]
            ),
            "data_bytes": content_end - executable_end,
            "p256_private_bytes": (
                addresses["p256_prime"] - executable_end
            ),
            "common_block_bytes": vector_start - addresses["p256_prime"],
            "read_only_vector_bytes": work_start - vector_start,
            "auth_working_bytes": strings_start - work_start,
            "string_bytes": content_end - strings_start,
        },
        "resumable_curve_checkpoint": {
            "boundary": "between complete Straus digit iterations",
            "bytes": sum(resumable_breakdown.values()),
            "breakdown": resumable_breakdown,
            "digits": "recode from retained u1/u2 after resume",
            "point_operation_scratch": "dead at this boundary",
        },
        "host_oracle": host,
        "target_gates": {
            "signature_der": target_der_matrix(
                image, addresses, fixture
            ),
            "affine_points": target_point_matrix(
                image, addresses, fixture
            ),
            "ecdsa": target_equations(image, addresses, fixture),
            "x509_spki_profile_scheme_context_time": False,
            "brotli_decoder": False,
        },
        "scope_labels": {
            "host_only": [
                "Brotli decompression and Certificate message parsing",
                "X.509 TBSCertificate/SPKI/profile/hostname parsing",
                "TLS CertificateVerify scheme/context reconstruction",
                "trusted validity time supplied by test fixture",
            ],
            "target_executed": [
                "canonical ECDSA signature DER and r/s range parsing",
                "P-256 affine coordinate range/on-curve checks",
                "mod-n inverse and two modular multiplications per signature",
                "on-target G/WE1/leaf width-4 table generation",
                "two-base Straus u1G+u2Q and x mod n comparison",
                "leaf-under-WE1 then CertificateVerify-under-leaf ordering",
            ],
        },
    }
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
